      "entity_backwash": "Povratno ispiranje (uključeno = u toku)",
      "entity_brine": "Usisavanje slane vode (uključeno = u toku)",
      "entity_refill": "Dopuna vodom (uključeno = u radu)",
      "entity_service": "U radu (uključeno = u radu)",
      "entity_rinse": "Ispiranje (uključeno = u radu)",
