      "entity_tank": "Rezervoar za vodu (pun / nivo)",
      "temp_step": "Korak temperature",
      "entity_frequency": "Compressor frequency",
      "entity_demand": "Demand (%)",
      "entity_outdoor_temp": "Outdoor temperature",
      "entity_dhw_temp": "Hot water tank temperature",
      "entity_pump_1": "Zone 1 circulator",
      "entity_pump_2": "Zone 2 circulator",
